CREATE OR REPLACE VIEW v_game_rooms AS SELECT g."ID_ИГРЫ" game_id,g."НАЗВАНИЕ" game_name,g."КОД_СТАТУСА_ИГРЫ" status_code,s."НАИМЕНОВАНИЕ" status_name,g."МАКС_ИГРОКОВ" max_players,COUNT(CASE WHEN u."КОД_СТАТУСА_УЧАСТНИКА"='В_ЛОББИ' THEN 1 END) lobby_players FROM "ИГРЫ" g JOIN "СТАТУСЫ_ИГР" s ON s."КОД_СТАТУСА_ИГРЫ"=g."КОД_СТАТУСА_ИГРЫ" LEFT JOIN "УЧАСТНИКИ" u ON u."ID_ИГРЫ"=g."ID_ИГРЫ" GROUP BY g."ID_ИГРЫ",g."НАЗВАНИЕ",g."КОД_СТАТУСА_ИГРЫ",s."НАИМЕНОВАНИЕ",g."МАКС_ИГРОКОВ";
